# (id, topic, title, text, source, related questions)
DOCS = [
    # ---- solar system & planets
    ("ss-overview", "solar system", "Our Solar System", "The Solar System is the Sun and everything that orbits it: eight planets, their moons, dwarf planets such as Pluto, asteroids and comets. The four inner planets (Mercury, Venus, Earth, Mars) are rocky. Jupiter and Saturn are gas giants, and Uranus and Neptune are ice giants.", "solar-system", ["Why are the inner planets rocky?", "What is a dwarf planet?"]),
    ("ss-formation", "solar system", "How the Solar System formed", "About 4.6 billion years ago a cloud of gas and dust collapsed. Most of the material formed the Sun, and the rest flattened into a spinning disk where dust and ice clumped together to build planets. That is why the planets orbit in nearly the same flat plane and in the same direction.", "solar-system", ["Why do planets orbit in the same direction?", "How old is the Sun?"]),
    ("ss-pluto", "solar system", "Pluto and dwarf planets", "Pluto was reclassified as a dwarf planet in 2006. A dwarf planet orbits the Sun and is round, but has not cleared other objects from its orbital neighbourhood. NASA's New Horizons flew past Pluto in 2015 and found mountains of water ice and a large heart-shaped plain of nitrogen ice.", "solar-system", ["Why isn't Pluto a planet anymore?", "What is the Kuiper Belt?"]),
    ("ss-kuiper", "solar system", "Kuiper Belt and Oort Cloud", "Beyond Neptune lies the Kuiper Belt, a ring of icy bodies including Pluto. Much farther out, scientists think a huge, spherical Oort Cloud of icy objects surrounds the Solar System; it has not been observed directly, but long-period comets suggest it exists.", "solar-system", ["Where do comets come from?", "How far away is the Oort Cloud?"]),
    ("ss-asteroids", "solar system", "Asteroids", "Asteroids are rocky leftovers from the formation of the planets. Most orbit in the main asteroid belt between Mars and Jupiter. NASA's DART mission in 2022 crashed into the small asteroid Dimorphos and successfully changed its orbit, testing a way to defend Earth.", "solar-system", ["Could an asteroid hit Earth?", "What did the DART mission do?"]),
    ("ss-comets", "solar system", "Comets", "Comets are 'dirty snowballs' of ice, dust and rock. When a comet comes close to the Sun, its ice turns to gas, forming a glowing coma and tails that point away from the Sun. Halley's Comet returns about every 76 years.", "solar-system", ["Why do comet tails point away from the Sun?", "When will Halley's Comet return?"]),
    ("ss-meteors", "solar system", "Meteors and meteorites", "A meteoroid is a small space rock. When it burns up in Earth's atmosphere we see a streak of light called a meteor, or 'shooting star'. If a piece survives and lands on the ground, it is called a meteorite.", "solar-system", ["What is a meteor shower?", "Are shooting stars really stars?"]),
    ("mercury-facts", "planets", "Mercury", "Mercury is the smallest planet and closest to the Sun, orbiting in about 88 Earth days. It has almost no atmosphere, so its day side reaches about 430°C while the night side drops to about −180°C. MESSENGER orbited it from 2011 to 2015, and the ESA–JAXA BepiColombo mission was launched in 2018.", "mercury", ["Why is Mercury not the hottest planet?", "Does Mercury have ice?"]),
    ("venus-facts", "planets", "Venus", "Venus is about Earth's size but is the hottest planet, around 465°C, because its thick carbon-dioxide atmosphere traps heat (a runaway greenhouse effect). Its clouds contain sulfuric acid, its surface pressure is about 90 times Earth's, and it spins backwards, very slowly.", "venus", ["Why is Venus hotter than Mercury?", "Could humans ever visit Venus?"]),
    ("earth-facts", "planets", "Earth", "Earth is the only place known to have life. About 71% of its surface is ocean. Its atmosphere is about 78% nitrogen and 21% oxygen, and its magnetic field and atmosphere protect life from much harmful radiation from space.", "earth", ["Why does Earth have seasons?", "Why is Earth's sky blue?"]),
    ("earth-seasons", "earth science", "Why Earth has seasons", "Earth's axis is tilted about 23.5 degrees. As Earth orbits the Sun, each hemisphere takes turns leaning toward the Sun, getting more direct sunlight and longer days (summer) or less direct sunlight (winter). Seasons are not caused by Earth getting closer to or farther from the Sun.", "earth", ["Why is it summer in Australia when it's winter in Europe?", "Does Mars have seasons?"]),
    ("mars-facts", "planets", "Mars", "Mars is red because its dust contains iron oxide (rust). Its atmosphere is very thin, mostly carbon dioxide, and less than 1% of Earth's surface pressure. Gravity is about 38% of Earth's, a day lasts 24 hours 37 minutes, and it has two small moons, Phobos and Deimos.", "mars", ["Why is Mars red?", "Can humans live on Mars?"]),
    ("mars-water", "planets", "Water on Mars", "Mars has water ice at its poles and under the ground. Dried river channels, lake deposits and minerals that form in water show that liquid water flowed on Mars long ago. Today liquid water cannot last on the surface because the air is so thin and cold.", "mars", ["Where did Mars's water go?", "Could there be life on Mars?"]),
    ("mars-life", "astrobiology", "Is there life on Mars?", "No life has been found on Mars. Scientists study whether Mars could have supported microbes in the past, when it had liquid water. The Perseverance rover collects rock samples that may one day be brought to Earth for detailed study. Whether Mars ever had life is still an open question.", "mars", ["What is Perseverance looking for?", "What is astrobiology?"]),
    ("jupiter-facts", "planets", "Jupiter", "Jupiter is the largest planet, made mostly of hydrogen and helium, with no solid surface like Earth's. Its Great Red Spot is a giant storm wider than Earth. Jupiter's strong gravity holds many moons, including Ganymede, the largest moon in the Solar System, volcanic Io and icy Europa.", "jupiter", ["Why does Jupiter have so many moons?", "What is the Great Red Spot?"]),
    ("europa", "moons", "Europa", "Jupiter's moon Europa has an icy shell that likely covers a salty ocean of liquid water. Because life on Earth needs liquid water, Europa is one of the best places to search for conditions suitable for life. NASA's Europa Clipper launched in 2024 to study it.", "jupiter", ["Could Europa have life?", "How thick is Europa's ice?"]),
    ("saturn-facts", "planets", "Saturn", "Saturn is a gas giant famous for its bright rings made of ice and rock. It is less dense than water on average. Its largest moon, Titan, has a thick atmosphere and lakes of liquid methane and ethane. The Cassini spacecraft studied Saturn from 2004 to 2017.", "saturn", ["What are Saturn's rings made of?", "What is Titan like?"]),
    ("enceladus", "moons", "Enceladus", "Saturn's small moon Enceladus sprays jets of water vapour and ice from cracks near its south pole. Cassini flew through these plumes and found salts and organic molecules, evidence of an underground ocean.", "saturn", ["Why does Enceladus have geysers?", "Could Enceladus have life?"]),
    ("uranus-facts", "planets", "Uranus", "Uranus is an ice giant tilted about 98 degrees, so it spins on its side. A year lasts about 84 Earth years. Methane in its atmosphere absorbs red light, giving it a blue-green colour. Voyager 2 is the only spacecraft to visit, flying past in 1986.", "uranus", ["Why is Uranus tilted?", "What are ice giants made of?"]),
    ("neptune-facts", "planets", "Neptune", "Neptune is the farthest planet, about 30 times farther from the Sun than Earth. It has the fastest winds measured in the Solar System, faster than 2,000 km/h. It was found in 1846 using mathematics, and Voyager 2 flew past in 1989. Its largest moon Triton orbits backwards.", "neptune", ["Why are Neptune's winds so fast?", "How was Neptune discovered?"]),
    ("planet-order", "solar system", "Planet order and distances", "In order from the Sun: Mercury, Venus, Earth, Mars, Jupiter, Saturn, Uranus, Neptune. Distances are often measured in astronomical units (AU); 1 AU is the average Earth–Sun distance, about 150 million km. Neptune is about 30 AU away.", "factsheet", ["What is an astronomical unit?", "How long would it take to fly to Neptune?"]),
    ("moon-facts", "moons", "Earth's Moon", "The Moon is Earth's only natural satellite, about 384,000 km away. Its gravity is about one-sixth of Earth's. The Moon always shows the same face to Earth because it is tidally locked. Twelve astronauts walked on the Moon during NASA's Apollo missions between 1969 and 1972.", "moon", ["Why does the Moon change shape?", "Why do we always see the same side of the Moon?"]),
    ("moon-phases", "moons", "Moon phases", "The Moon seems to change shape during the month, but it does not really change. It does not make its own light; it reflects sunlight. As it orbits Earth about once a month, we see different amounts of its sunlit half, giving the phases: new moon, crescent, quarter, gibbous and full moon.", "moon", ["What causes a lunar eclipse?", "Is there a dark side of the Moon?"]),
    ("eclipses", "astronomy", "Eclipses", "A solar eclipse happens when the Moon passes between the Sun and Earth, blocking sunlight. A lunar eclipse happens when Earth's shadow falls on the Moon, often turning it reddish. Never look directly at the Sun during a solar eclipse without proper eclipse glasses.", "moon", ["Why is the Moon red during a lunar eclipse?", "How often do eclipses happen?"]),
    ("tides", "earth science", "Tides", "Ocean tides are caused mostly by the Moon's gravity pulling on Earth's oceans, with help from the Sun. Most coasts get two high tides and two low tides about every day.", "moon", ["Why are there two high tides a day?", "Does the Sun cause tides too?"]),
    # ---- sun, stars, galaxies, universe
    ("sun-facts", "stars", "The Sun", "The Sun is a star, a huge ball of hot plasma made mostly of hydrogen and helium. In its core, nuclear fusion turns hydrogen into helium and releases energy. Its surface is about 5,500°C. Sunlight takes about 8 minutes 20 seconds to reach Earth.", "sun", ["How long will the Sun shine?", "What is nuclear fusion?"]),
    ("sun-future", "stars", "The Sun's future", "The Sun is about 4.6 billion years old and is roughly halfway through its life. In about 5 billion years it will swell into a red giant, then shrink into a white dwarf. It is not massive enough to become a black hole.", "sun", ["Will the Sun become a black hole?", "What is a red giant?"]),
    ("space-weather", "space weather", "Solar flares and space weather", "Solar flares are bursts of energy from the Sun. Coronal mass ejections (CMEs) are huge clouds of magnetised gas thrown into space. When they reach Earth they can cause auroras and geomagnetic storms that may disturb satellites, radio, GPS and power grids. NOAA's Space Weather Prediction Center issues alerts.", "swpc", ["What causes auroras?", "Can solar storms hurt people on Earth?"]),
    ("auroras", "space weather", "Auroras", "Auroras (northern and southern lights) glow when charged particles from the Sun, guided by Earth's magnetic field, collide with oxygen and nitrogen high in the atmosphere. Oxygen often glows green or red, and nitrogen can glow blue or purple.", "swpc", ["Why are auroras green?", "Do other planets have auroras?"]),
    ("stars-life", "stars", "Life of a star", "Stars form in clouds of gas and dust called nebulae. They shine by fusing hydrogen. Small and medium stars like the Sun end as white dwarfs; very massive stars explode as supernovae and can leave behind neutron stars or black holes.", "universe", ["What is a supernova?", "What is a neutron star?"]),
    ("star-colours", "stars", "Star colours", "A star's colour tells us its surface temperature. Blue stars are the hottest, white and yellow stars like the Sun are in the middle, and red stars are the coolest.", "universe", ["Why do stars twinkle?", "What is the hottest kind of star?"]),
    ("star-twinkle", "stars", "Why stars twinkle", "Stars twinkle because their light passes through moving layers of Earth's air, which bend the light slightly in changing directions. Planets usually twinkle less because they appear as tiny discs rather than points.", "spaceplace", ["Do stars twinkle in space?", "How can I tell a planet from a star?"]),
    ("nearest-star", "stars", "Nearest stars", "After the Sun, the nearest star is Proxima Centauri, about 4.2 light-years away. A light-year is the distance light travels in one year, about 9.46 trillion km.", "universe", ["What is a light-year?", "Could we travel to another star?"]),
    ("light-year", "physics", "Light-years and the speed of light", "Light travels about 300,000 km every second. A light-year is a distance, not a time: how far light travels in one year. When we look at distant stars and galaxies we see light that left them long ago, so we see them as they were in the past.", "universe", ["Is a light-year a time?", "Are we seeing stars that no longer exist?"]),
    ("black-holes", "black holes", "Black holes", "A black hole is a region where gravity is so strong that nothing, not even light, can escape. Stellar black holes can form when very massive stars collapse. Supermassive black holes sit at the centres of most large galaxies. In 2019 the Event Horizon Telescope released the first image of a black hole's shadow, in galaxy M87.", "universe", ["What would happen if you fell into a black hole?", "Is there a black hole in our galaxy?"]),
    ("sgr-a", "black holes", "The black hole in our galaxy", "At the centre of the Milky Way is a supermassive black hole called Sagittarius A*, about 4 million times the mass of the Sun. Astronomers confirmed it by tracking stars orbiting it, and an image of its shadow was released in 2022.", "universe", ["How do we know black holes exist?", "Will the Milky Way's black hole swallow Earth?"]),
    ("black-hole-safety", "black holes", "Black holes are not cosmic vacuum cleaners", "A black hole does not suck everything in. Far away, its gravity acts like that of any object with the same mass. If the Sun were replaced by a black hole of the same mass, Earth's orbit would not change (though it would be dark and cold).", "universe", ["Could a black hole eat Earth?", "How big is a black hole?"]),
    ("galaxies", "galaxies", "Galaxies", "A galaxy is a huge collection of stars, gas, dust and dark matter held together by gravity. Our galaxy, the Milky Way, is a barred spiral with roughly 100 to 400 billion stars. The Andromeda Galaxy, about 2.5 million light-years away, is the nearest large spiral galaxy.", "universe", ["How many galaxies are there?", "Will the Milky Way crash into Andromeda?"]),
    ("universe-age", "universe", "Age of the universe", "Scientists estimate the universe is about 13.8 billion years old. Evidence comes from the cosmic microwave background (leftover heat from the early universe) and from galaxies moving apart as the universe expands, which is the basis of the Big Bang theory.", "universe", ["What was before the Big Bang?", "Is the universe still expanding?"]),
    ("dark-matter", "universe", "Dark matter and dark energy", "Most of the universe is made of things we cannot see directly. Dark matter adds gravity that holds galaxies together, and dark energy is linked to the universe's accelerating expansion. Scientists do not yet know what either one is made of; this is an active area of research.", "universe", ["What is dark matter made of?", "How do we know dark matter exists?"]),
    ("exoplanets", "astronomy", "Exoplanets", "Exoplanets are planets that orbit other stars. Thousands have been confirmed, mostly found by watching stars dim slightly when a planet passes in front (the transit method). No life has been confirmed on any exoplanet yet.", "universe", ["How do we find exoplanets?", "Is there another Earth?"]),
    ("webb", "telescopes", "James Webb Space Telescope", "The James Webb Space Telescope launched in December 2021. It observes mainly in infrared light, letting it see very distant early galaxies and look through dust where stars are born. It orbits the Sun about 1.5 million km from Earth, near a spot called L2.", "webb", ["Why does Webb use infrared?", "How is Webb different from Hubble?"]),
    ("hubble", "telescopes", "Hubble Space Telescope", "The Hubble Space Telescope launched in 1990 and orbits Earth. Above the blurring effects of the atmosphere, it has taken sharp images of galaxies, nebulae and planets and helped measure how fast the universe is expanding.", "universe", ["Why put telescopes in space?", "What has Hubble discovered?"]),
    # ---- exploration, rockets, satellites
    ("rockets", "rockets", "How rockets work", "Rockets work by Newton's third law: for every action there is an equal and opposite reaction. Engines push hot gas out of the back at high speed, and the gas pushes the rocket forward. Rockets carry their own oxygen (oxidiser) because there is no air in space.", "spaceplace", ["Why do rockets have stages?", "How fast does a rocket go?"]),
    ("rocket-stages", "rockets", "Rocket stages", "Large rockets use stages. When a stage runs out of fuel it drops away, so the rocket no longer carries its empty weight. This makes it much easier to reach the speed needed for orbit, about 28,000 km/h for low Earth orbit.", "spaceplace", ["What is orbital speed?", "Can rockets be reused?"]),
    ("orbits", "physics", "What is an orbit?", "An orbit is the curved path of an object around a planet or star. A satellite moves sideways very fast while gravity pulls it down, so it keeps falling around Earth instead of hitting it. Isaac Newton imagined this with a cannonball fired faster and faster from a mountain.", "spaceplace", ["Why don't satellites fall down?", "What is Newton's cannonball?"]),
    ("satellites", "satellites", "Satellites", "Satellites are objects that orbit a planet. Artificial satellites help with weather forecasting, GPS navigation, TV, internet and studying Earth's climate. Geostationary satellites orbit about 35,800 km up and stay over the same spot on Earth.", "earth", ["How does GPS work?", "How many satellites are there?"]),
    ("gps", "satellites", "How GPS works", "GPS receivers listen to signals from several satellites. Each signal carries a precise time. By measuring how long signals take to arrive from at least four satellites, the receiver works out its position. GPS satellites even account for tiny time effects predicted by Einstein's relativity.", "spaceplace", ["Why does GPS need four satellites?", "What does relativity have to do with GPS?"]),
    ("apollo", "space exploration", "Apollo Moon landings", "On 20 July 1969, Apollo 11 astronauts Neil Armstrong and Buzz Aldrin became the first people to walk on the Moon, while Michael Collins orbited above. Six Apollo missions landed between 1969 and 1972 and brought back 382 kg of Moon rocks.", "moon", ["What did astronauts bring back from the Moon?", "Will people go back to the Moon?"]),
    ("artemis", "space exploration", "Artemis program", "NASA's Artemis program aims to return people to the Moon and build a long-term presence there as a step toward Mars. Artemis I, an uncrewed test flight around the Moon, flew in 2022. Exact dates for later crewed missions can change, so check NASA for the latest schedule.", "moon", ["Who will go on Artemis missions?", "Why go back to the Moon?"]),
    ("voyager", "space exploration", "Voyager probes", "Voyager 1 and 2 launched in 1977. Voyager 2 is the only spacecraft to visit Uranus and Neptune. Both have left the heliosphere and are in interstellar space, still sending data with power from radioisotope generators.", "solar-system", ["How far away is Voyager 1?", "What is on the Golden Record?"]),
    ("mars-rovers", "space exploration", "Mars rovers", "NASA rovers on Mars include Sojourner (1997), Spirit and Opportunity (2004), Curiosity (2012) and Perseverance (2021). Perseverance carried Ingenuity, the first helicopter to fly on another planet. Rovers drive slowly and carefully because no one can repair them.", "mars", ["How do rovers get power?", "How do you drive a rover on Mars?"]),
    ("deep-space-network", "communication", "Talking to spacecraft", "NASA's Deep Space Network uses giant antennas in California, Spain and Australia so that at least one can always see a spacecraft as Earth turns. Radio signals travel at the speed of light, yet still take minutes to hours to reach distant spacecraft.", "solar-system", ["How long does a message take to reach Mars?", "Why do spacecraft need big antennas?"]),
    ("probes-power", "space technology", "Powering spacecraft", "Spacecraft near the Sun usually use solar panels. Far from the Sun, sunlight is too weak, so probes like Voyager and the Curiosity rover use radioisotope generators that turn heat from decaying plutonium-238 into electricity.", "solar-system", ["Why can't Voyager use solar panels?", "How long do spacecraft batteries last?"]),
    # ---- astronauts
    ("iss", "astronauts", "International Space Station", "The International Space Station orbits about 400 km above Earth, circling it about every 90 minutes at about 28,000 km/h. Astronauts from many countries have lived aboard continuously since November 2000, doing science experiments.", "iss", ["How do astronauts sleep in space?", "Can you see the ISS from Earth?"]),
    ("weightlessness", "astronauts", "Why astronauts float", "Astronauts on the space station float because they and the station are falling around Earth together (free fall). Gravity there is still about 90% as strong as on the ground.", "iss", ["Is there gravity in space?", "How do astronauts exercise?"]),
    ("spacesuits", "astronauts", "Spacesuits and helmets", "Space has almost no air pressure and no oxygen. A spacesuit is like a small personal spacecraft: it supplies oxygen, keeps pressure around the body, controls temperature and shields from sunlight and tiny debris. Without a suit, a person would lose consciousness within about 15 seconds.", "humans", ["What happens if astronauts remove their helmets?", "Why are spacesuits white?"]),
    ("astronaut-life", "astronauts", "Daily life in space", "Astronauts sleep in small cabins in sleeping bags tied to the wall, eat specially packaged food, and exercise about two hours a day to keep their bones and muscles strong in microgravity. Water is recycled, including from sweat and urine, and purified to be drinkable.", "iss", ["What do astronauts eat?", "How do astronauts go to the toilet in space?"]),
    ("space-body", "astronauts", "Space and the human body", "In microgravity, bones and muscles weaken without exercise, body fluids shift toward the head, and astronauts may grow slightly taller because the spine stretches. Space radiation is another risk, especially beyond Earth's magnetic field.", "humans", ["Do astronauts get taller in space?", "How do astronauts stay healthy?"]),
    ("become-astronaut", "astronauts", "Becoming an astronaut", "Astronauts usually study science, technology, engineering, mathematics or medicine, or are experienced pilots. They train for years in spacewalk practice pools, flight simulators, survival skills, robotics and teamwork.", "humans", ["How do astronauts practise spacewalks?", "What subjects should I study to work in space?"]),
    # ---- physics & maths
    ("gravity", "physics", "Gravity", "Gravity is the attraction between objects with mass. The more mass, the stronger the pull, and the pull gets weaker with distance. Gravity keeps us on the ground, holds the Moon in orbit around Earth and keeps planets orbiting the Sun.", "spaceplace", ["Why do things fall at the same speed?", "Is there gravity on the Moon?"]),
    ("mass-weight", "physics", "Mass and weight", "Mass is how much matter something has; it stays the same everywhere. Weight is the force of gravity on that mass, so it changes from planet to planet. On the Moon you would weigh about one-sixth of your Earth weight, but your mass would be the same.", "factsheet", ["How much would I weigh on Mars?", "What is the difference between mass and weight?"]),
    ("newton-laws", "physics", "Newton's laws of motion", "Newton's first law: objects keep moving or stay still unless a force acts. Second law: force equals mass times acceleration (F = ma). Third law: every action has an equal and opposite reaction, which is how rockets move.", "spaceplace", ["Why does a ball stop rolling?", "How do Newton's laws help rockets?"]),
    ("inverse-square", "physics", "The inverse-square law", "Light and gravity spread out over larger areas as distance grows. Double the distance and the strength falls to one quarter (1/2²). This is why sunlight at Neptune, about 30 AU away, is roughly 900 times weaker than at Earth.", "factsheet", ["Why is it so cold on Neptune?", "Does gravity also follow the inverse-square law?"]),
    ("kepler", "physics", "Kepler's laws", "Johannes Kepler found that planets move in ellipses, move faster when closer to the Sun, and that the square of a planet's year equals the cube of its average distance (T² = a³, with T in years and a in AU). For Mars, a = 1.52 AU gives T ≈ 1.88 years.", "factsheet", ["Why do planets move faster near the Sun?", "Who was Johannes Kepler?"]),
    ("speed-of-sound", "physics", "Sound in space", "Sound needs a medium such as air or water to travel through. Space is nearly a vacuum, so sound cannot travel through it. Astronauts talk to each other by radio.", "spaceplace", ["Is space completely silent?", "How do astronauts talk on a spacewalk?"]),
    ("sci-notation", "mathematics", "Big numbers in space", "Space distances are huge, so scientists use scientific notation: 150,000,000 km can be written 1.5 × 10^8 km. Each power of ten adds a zero. Units such as AU and light-years also keep numbers manageable.", "spaceplace", ["How do you write a trillion in scientific notation?", "Why do astronomers use light-years?"]),
    ("speed-maths", "mathematics", "Speed, distance and time", "Speed = distance ÷ time. For example, light travels about 300,000 km per second, so to cross 150 million km (Earth to Sun) it needs about 150,000,000 ÷ 300,000 = 500 seconds, a little over 8 minutes.", "spaceplace", ["How long would a car take to drive to the Moon?", "How fast does Earth move around the Sun?"]),
    # ---- earth & environment
    ("atmosphere-layers", "earth science", "Earth's atmosphere", "Earth's atmosphere has layers: the troposphere (where weather happens), the stratosphere (with the ozone layer), the mesosphere (where most meteors burn up), the thermosphere (where the ISS and auroras are) and the exosphere. Air gets thinner with height.", "earth", ["Where does space begin?", "What does the ozone layer do?"]),
    ("ozone", "earth science", "The ozone layer", "The ozone layer in the stratosphere absorbs most of the Sun's harmful ultraviolet light. After chemicals called CFCs were found to damage it, countries agreed in the 1987 Montreal Protocol to phase them out, and the ozone layer is slowly recovering.", "earth", ["What is the ozone hole?", "How can we protect the ozone layer?"]),
    ("greenhouse", "environment", "The greenhouse effect and climate change", "Greenhouse gases such as carbon dioxide and methane trap heat and keep Earth warm enough for life. Burning fossil fuels adds more carbon dioxide, which is warming Earth's climate. NASA satellites measure changes in temperature, sea level and ice.", "earth", ["How do satellites study climate change?", "What can kids do to help the climate?"]),
    ("water-cycle", "earth science", "The water cycle", "The Sun's energy evaporates water from oceans and lakes. The vapour rises, cools and condenses into clouds, then falls as rain or snow, flowing back to rivers and oceans. Satellites help track rainfall and water around the world.", "earth", ["Where does rain come from?", "Is there a water cycle on other planets?"]),
    ("earth-from-space", "environment", "Studying Earth from space", "Earth-observing satellites track weather, wildfires, floods, crops, sea ice and pollution. Their data helps forecasters warn people about storms and helps scientists understand how our planet is changing.", "earth", ["How do weather satellites work?", "Can satellites see wildfires?"]),
    ("magnetosphere", "earth science", "Earth's magnetic field", "Earth's liquid iron outer core produces a magnetic field. The magnetosphere it creates deflects most of the solar wind, protecting the atmosphere and life. Compass needles line up with this field.", "earth", ["Why does Earth have a magnetic field?", "Does Mars have a magnetic field?"]),
    ("habitable-zone", "astrobiology", "The habitable zone", "The habitable zone is the range of distances from a star where a planet could have liquid water on its surface. Earth is in the Sun's habitable zone. Being in this zone does not guarantee life; the planet also needs the right atmosphere and other conditions.", "universe", ["Is Mars in the habitable zone?", "What makes a planet habitable?"]),
    ("life-search", "astrobiology", "Searching for life", "Scientists look for life where there is liquid water, energy and the right chemistry, such as Mars, Europa and Enceladus, and study exoplanet atmospheres. So far, no life beyond Earth has been confirmed.", "universe", ["Are we alone in the universe?", "What would alien life look like?"]),
    ("esa-missions", "space exploration", "European space missions", "The European Space Agency (ESA) leads missions such as Rosetta, which landed the Philae probe on a comet in 2014, and JUICE, launched in 2023 to study Jupiter's icy moons. ESA also partners with NASA on Webb and with Japan on BepiColombo.", "esa", ["What did Rosetta discover?", "What will JUICE study?"]),
    ("space-debris", "space technology", "Space debris", "Old satellites, rocket parts and tiny fragments orbit Earth as space debris. Even small pieces move very fast and can damage spacecraft, so agencies track larger debris and the ISS can move to avoid it.", "iss", ["How do we clean up space junk?", "Has space debris ever hit the ISS?"]),
]

DOC_INDEX = {d[0]: d for d in DOCS}


def doc_record(doc):
    did, topic, title, text, source, related = doc
    name, url = SOURCES[source]
    return {"id": did, "topic": topic, "title": title, "text": text, "source": name, "url": url, "related": related}
